    if (Physics.Raycast(ray, out RaycastHit hit, 100f, enemies)) { /* … */ }
    Status s = Status.Burning | Status.Stunned;                 // 0b101
    bool stunned = (s & Status.Stunned) != 0;                   // no HasFlag
}

