public int HammingWeight(int n) {
    uint x = (uint)n;              // the same 32 bits, no sign
    int count = 0;
    while (x != 0) {               // a uint shifts in zeros, so the loop ends
        count += (int)(x & 1);     // the lowest bit
        x >>= 1;
    }
    return count;                  // up to 32 steps, even for a single 1 in bit 31
}

