public int HammingDistance(int x, int y) => PopCount((uint)(x ^ y));
public int MinBitFlips(int start, int goal) => PopCount((uint)(start ^ goal));   // #2220 is the same problem

static int PopCount(uint v) {
#if NETCOREAPP3_0_OR_GREATER
    return System.Numerics.BitOperations.PopCount(v);
#else
    int c = 0;                                   // Unity: math.countbits(v) or Kernighan
    for (; v != 0; v &= v - 1) c++;
    return c;
#endif
}

