static int PopCountSwar(uint x) {
    x = x - ((x >> 1) & 0x55555555);                 // each pair of bits holds the pair's sum
    x = (x & 0x33333333) + ((x >> 2) & 0x33333333);  // each nibble holds the nibble's sum
    x = (x + (x >> 4)) & 0x0F0F0F0F;                 // each byte holds the byte's sum
    return (int)((x * 0x01010101) >> 24);            // the multiply adds all bytes into the top one
}
